function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 70);
  ctx.lineTo(W/2 - 50, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 70);
  ctx.lineTo(W/2 + 50, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 20 * Math.sin(t), H/2 - 20 - 20 * Math.cos(t));
  ctx.lineTo(W/2 - 40 + 20 * Math.sin(t), H/2 - 40 - 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 + 20 * Math.sin(t), H/2 - 20 - 20 * Math.cos(t));
  ctx.lineTo(W/2 + 40 + 20 * Math.sin(t), H/2 - 40 - 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
